package io.bmsride.monitor;
import java.util.*;
public class ProtocolTest {
 static void putbe(byte[] a,int i,int v){a[i]=(byte)(v>>8);a[i+1]=(byte)v;}static void putle(byte[] a,int i,int v){a[i]=(byte)v;a[i+1]=(byte)(v>>8);}static void put32(byte[] a,int i,int v){putle(a,i,v);putle(a,i+2,v>>16);}
 static byte[] jbd(int reg,byte[] p){byte[] a=new byte[p.length+7];a[0]=(byte)0xdd;a[1]=(byte)reg;a[3]=(byte)p.length;System.arraycopy(p,0,a,4,p.length);int s=p.length;for(byte b:p)s+=b&255;putbe(a,a.length-3,-s);a[a.length-1]=0x77;return a;}
 static byte[] jk(int o){byte[] a=new byte[300];a[0]=0x55;a[1]=(byte)0xaa;a[2]=(byte)0xeb;a[3]=(byte)0x90;a[4]=2;for(int i=0;i<20;i++)putle(a,6+2*i,3700);put32(a,54+o,0xfffff);put32(a,118+2*o,74000);put32(a,126+2*o,-12400);putle(a,130+2*o,265);a[141+2*o]=78;put32(a,142+2*o,32700);putle(a,o==16?128:134,290);int s=0;for(int i=0;i<299;i++)s+=a[i]&255;a[299]=(byte)s;return a;}
 static void verify(Protocol.Battery b){if(b==null||b.cells.length!=20||b.soc!=78||Math.abs(b.voltage-74)>0.001||Math.abs(b.current+12.4)>0.001||Math.abs(b.ah-32.7)>0.001||Math.abs(b.temp-26.5)>0.001)throw new AssertionError("bad battery");}
 public static void main(String[] args){byte[] p=new byte[25];putbe(p,0,7400);putbe(p,2,-1240);putbe(p,4,3270);p[19]=78;p[21]=20;p[22]=1;putbe(p,23,2996);byte[] c=new byte[40];for(int i=0;i<20;i++)putbe(c,i*2,3700);Protocol.Decoder d=new Protocol.Decoder(Protocol.Kind.JBD);if(d.feed(jbd(3,p),1)!=null)throw new AssertionError();byte[] a=jbd(4,c);if(d.feed(Arrays.copyOfRange(a,0,20),2)!=null)throw new AssertionError();verify(d.feed(Arrays.copyOfRange(a,20,a.length),3));System.out.println("PASS JBD 20S + split frames");for(Protocol.Kind k:new Protocol.Kind[]{Protocol.Kind.JK24,Protocol.Kind.JK32}){byte[] f=jk(k==Protocol.Kind.JK32?16:0);d=new Protocol.Decoder(k);if(d.feed(Arrays.copyOfRange(f,0,123),1)!=null)throw new AssertionError();verify(d.feed(Arrays.copyOfRange(f,123,300),2));f[299]^=1;if(new Protocol.Decoder(k).feed(f,3)!=null)throw new AssertionError();System.out.println("PASS "+k+" split + checksum rejection");}System.out.println("PASS all synthetic tests");}
}
